import{_ as e,o as a,c as s,a2 as d}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"网络","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/network.md","filePath":"zh/manual/network.md"}'),n={name:"zh/manual/network.md"};function o(c,t,i,r,l,p){return a(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h1><p>一个自包含的 TCP/IP 协议栈，从网卡驱动到 SSH 服务器一应俱全——没有移植的 libc，也没有第三方代码。</p><h2 id="点亮" tabindex="-1">点亮 <a class="header-anchor" href="#点亮" aria-label="Permalink to &quot;点亮&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; dhcp                  (request an address on nic0)</span></span>
<span class="line"><span>oc&gt; ping 10.0.2.2         (ICMP echo to the QEMU gateway)</span></span>
<span class="line"><span>oc&gt; dns example.com       (resolve via the QEMU DNS forwarder)</span></span>
<span class="line"><span>oc&gt; wget 10.0.2.2         (fetch http://10.0.2.2/)</span></span>
<span class="line"><span>oc&gt; wget host 8080 /path  (explicit port and path)</span></span>
<span class="line"><span>oc&gt; route                 (routing table)</span></span>
<span class="line"><span>oc&gt; tcpstats              (TCP counters + congestion state)</span></span>
<span class="line"><span>oc&gt; firewall              (stateful firewall rules)</span></span></code></pre></div><p>在 QEMU 中，默认的 <code>-device e1000</code> 能直接匹配 e1000 驱动：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 -m 512 -cdrom opencube.iso \\</span></span>
<span class="line"><span>    -netdev user,id=n1 -device e1000,netdev=n1</span></span></code></pre></div><h2 id="支持的网卡" tabindex="-1">支持的网卡 <a class="header-anchor" href="#支持的网卡" aria-label="Permalink to &quot;支持的网卡&quot;">​</a></h2><table tabindex="0"><thead><tr><th>系列</th><th>卡片</th><th>驱动</th></tr></thead><tbody><tr><td>Intel e1000</td><td>e1000 (8254x)</td><td><code>drivers/nic/driver_nic.c</code></td></tr><tr><td>Intel e1000e</td><td>8257x ICH/PCH 网卡</td><td><code>driver_nic_e1000e.c</code></td></tr><tr><td>Intel igb</td><td>82575/82576（含虚拟功能）</td><td><code>driver_nic_igb.c</code></td></tr><tr><td>Intel ixgbe</td><td>82598/82599 10 千兆以太网</td><td><code>driver_nic_ixgbe.c</code></td></tr><tr><td>Realtek rtl8139</td><td>8139/810x 快速以太网</td><td><code>driver_nic_rtl8139.c</code></td></tr><tr><td>Realtek rtl8169</td><td>8168/8125/810x 千兆系列</td><td><code>driver_nic_rtl8169.c</code></td></tr><tr><td>Broadcom BCM57xx</td><td>5708/5709/5714 时代</td><td><code>driver_nic_bcm57xx.c</code></td></tr></tbody></table><h2 id="协议栈" tabindex="-1">协议栈 <a class="header-anchor" href="#协议栈" aria-label="Permalink to &quot;协议栈&quot;">​</a></h2><p>ARP、IPv4、ICMP、UDP、DNS、拥塞控制 TCP（<code>net_tcp_cc.c</code>）、面向用户程序的套接字 API，以及有状态防火墙。每一层都可通过命令查看：<code>arp</code>、<code>route</code>、<code>tcpstats</code>、<code>firewall</code>、<code>nicstat</code>。</p><h2 id="https-客户端-tls-1-2-1-3" tabindex="-1">HTTPS 客户端（TLS 1.2 / 1.3） <a class="header-anchor" href="#https-客户端-tls-1-2-1-3" aria-label="Permalink to &quot;HTTPS 客户端（TLS 1.2 / 1.3）&quot;">​</a></h2><p><code>wget https://...</code> 通过 RSA 和 ECDHE 密钥交换协商 TLS，验证 X.509 链（RFC 6125 主机名策略——IP 字面 URL 无参考身份），并拒绝篡改的证书。加密核心（AES、SHA-2 家族、HMAC、RSA、NIST 曲线、Ed25519 风格原语）与 <code>cryptotest</code> 用 NIST 向量验证的代码相同。</p><p>DH 密钥交换正确性与时序：<code>dhtest</code>。</p><h2 id="ssh-客户端与服务器" tabindex="-1">SSH：客户端与服务器 <a class="header-anchor" href="#ssh-客户端与服务器" aria-label="Permalink to &quot;SSH：客户端与服务器&quot;">​</a></h2><ul><li><p><strong>客户端</strong>（<code>ssh</code> 命令）：连接、认证、运行远程命令——通过 curve25519 风格原语进行密钥交换。</p></li><li><p><strong>服务器</strong>（<code>sshd</code>）：一个真正在客户机内部的 SSH 服务器。主机和客户端密钥存储在 /etc 卷上（<code>host_keygen_etc</code> 为其生成）；授权密钥也在那里管理。从你的主机：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ssh -p &lt;port&gt; root@localhost     (forward a QEMU port to try it)</span></span></code></pre></div><p>端到端测试套件对客户机内的 sshd 执行完整的 paramiko 登录往返测试。</p></li></ul><h2 id="dns" tabindex="-1">DNS <a class="header-anchor" href="#dns" aria-label="Permalink to &quot;DNS&quot;">​</a></h2><p><code>dns &lt;name&gt;</code> 通过配置的解析器解析（QEMU 的用户模式栈会转发到主机）。缓存的条目可通过网络统计命令查看。</p><h2 id="缺失功能-诚实清单" tabindex="-1">缺失功能（诚实清单） <a class="header-anchor" href="#缺失功能-诚实清单" aria-label="Permalink to &quot;缺失功能（诚实清单）&quot;">​</a></h2><ul><li>未实现 IPv6。</li><li>Wi-Fi 关联：无线栈（<code>wifi</code> 命令）覆盖 ath/brcm/iwlwifi/rtlwifi 系列和 SDIO 总线上的状态/扫描/测试——真实硬件上的完整关联取决于网卡系列；在 QEMU 中没有可附加的 Wi-Fi 设备模型。</li><li>NAT 穿越/端口转发是 QEMU 用户模式的特性，而非内核功能。</li></ul>`,19)])])}const b=e(n,[["render",o]]);export{u as __pageData,b as default};
